package com.tnc.tnc.world.stonecrest;
import net.minecraft.core.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.world.level.ChunkPos;
import net.minecraftforge.gametest.*;
import java.util.*;
@GameTestHolder("tncrealm") @PrefixGameTestTemplate(false)
public final class HeroskandRealmGameTests {
 private static final org.slf4j.Logger LOG=com.mojang.logging.LogUtils.getLogger();
 @GameTest(template="empty",timeoutTicks=24000)
 public static void entireEstateGeneratesInItsOwnRealm(GameTestHelper h){var realm=h.getLevel().getServer().getLevel(HeroskandRealm.KEY);h.assertTrue(realm!=null,"dedicated dimension loads");h.assertTrue(realm.getWorldBorder().getSize()==1024,"small dedicated border");var manifest=StonecrestManifest.get("heroskand_estate_v2");var queue=new ArrayDeque<ChunkPos>();var start=new ChunkPos(HeroskandRealm.ORIGIN);var end=new ChunkPos(HeroskandRealm.ORIGIN.offset(manifest.dimensions().getX()-1,0,manifest.dimensions().getZ()-1));for(int z=start.z;z<=end.z;z++)for(int x=start.x;x<=end.x;x++)queue.add(new ChunkPos(x,z));int total=queue.size();class Pump {int generated,inflight;boolean done;void tick(){if(done)return;while(inflight<4&&!queue.isEmpty()){var c=queue.remove();inflight++;realm.getChunkSource().getChunkFuture(c.x,c.z,net.minecraft.world.level.chunk.ChunkStatus.FULL,true).whenCompleteAsync((result,error)->{inflight--;generated++;if(error!=null){done=true;h.fail("Realm generation failed: "+error);}if(generated%200==0)LOG.info("[TN-C Realm] generated {}/{}",generated,total);},realm.getServer());}if(queue.isEmpty()&&inflight==0){done=true;verify();}else h.runAfterDelay(1,this::tick);}
 void verify(){int verified=0,missing=0;long blocks=0;long mismatches=0,foliageConversions=0;var differences=new java.util.TreeMap<String,Integer>();for(var piece:manifest.pieces()){var manager=realm.getStructureManager();var template=manager.get(piece.resource()).orElseThrow();try{var nbt=template.save(new net.minecraft.nbt.CompoundTag());var palette=nbt.getList("palette",10);var entries=nbt.getList("blocks",10);boolean matched=false;for(int i=0;i<entries.size();i++){var entry=entries.getCompound(i);var stateTag=palette.getCompound(entry.getInt("state"));var id=net.minecraft.resources.ResourceLocation.tryParse(stateTag.getString("Name"));var block=net.minecraftforge.registries.ForgeRegistries.BLOCKS.getValue(id);h.assertTrue(block!=null&&!block.defaultBlockState().isAir(),"all source palette blocks are installed: "+id);var pos=entry.getList("pos",3);var at=HeroskandRealm.ORIGIN.offset(piece.offset()).offset(pos.getInt(0),pos.getInt(1),pos.getInt(2));var actual=realm.getBlockState(at);var replacement=com.tnc.tnc.world.ConquestPlantProcessor.replacement(id);var expected=block;if(replacement!=null){expected=replacement.getBlock();foliageConversions++;}if(actual.is(expected))matched=true;else{mismatches++;differences.merge(id+" -> "+net.minecraftforge.registries.ForgeRegistries.BLOCKS.getKey(actual.getBlock()),1,Integer::sum);}}if(!matched){missing++;LOG.error("[TN-C Realm] missing piece {} with {} blocks",piece.resource(),entries.size());}verified++;blocks+=entries.size();}finally{manager.remove(piece.resource());}}
 LOG.info("[TN-C Realm] FULL CHECK chunks={} pieces={} blocks={} missingPieces={} mismatchedBlocks={} persistentFoliageConversions={} differences={}",total,verified,blocks,missing,mismatches,foliageConversions,differences);h.assertTrue(mismatches==0,"source block identities must survive all native chunk joins: "+differences);h.assertTrue(missing==0,"every source piece survives native generation; missing="+missing);h.assertTrue(verified==3617&&blocks>9000000,"complete castle and landscape, not legacy fragment");h.succeed();}}
 new Pump().tick();
 }
}
